    // Packet builder for Sub Bass Gain (Mid SPK 0x99)
    public static byte[] buildSubGainPacket(int gainVal) {
        byte gLo = (byte) (gainVal & 0xFF);
        byte gHi = (byte) ((gainVal >> 8) & 0xFF);
        return new byte[] {
            (byte) 0xA5, (byte) 0x5A,
            (byte) 0x99,
            (byte) 0x07,
            (byte) 0xFF,
            (byte) 0x01, (byte) 0x00,
            (byte) 0x00, (byte) 0x00,
            gLo, gHi,
            (byte) 0x16
        };
    }

