    // Packet builder for MVBass Classic (0x87)
    public static byte[] buildMVBassPacket(int cutoffHz, int intensityPercent) {
        byte fcLo = (byte) (cutoffHz & 0xFF);
        byte fcHi = (byte) ((cutoffHz >> 8) & 0xFF);
        byte intLo = (byte) (intensityPercent & 0xFF);
        byte intHi = (byte) ((intensityPercent >> 8) & 0xFF);
        return new byte[] {
            (byte) 0xA5, (byte) 0x5A,
            (byte) 0x87,
            (byte) 0x0B,
            (byte) 0xFF,
            (byte) 0x01, (byte) 0x00,
            fcLo, fcHi,
            intLo, intHi,
            (byte) 0x00, (byte) 0x00,
            (byte) 0x00, (byte) 0x00,
            (byte) 0x16
        };
    }

