    // Live state buffers for real-time frequency pushing
    public static byte[] liveBassFrame = BASE_FRAME_BASS_95.clone();
    public static byte[] liveTrebleFrame = BASE_FRAME_TREBLE_96.clone();

    /**
     * Set the gain of a specific filter inside Bass EQ (0x95)
     * @param filterIdx 0-based filter index (0 to 9)
     * @param gainDb Gain in decibels (-18.0 to +18.0 dB)
     */
    public static byte[] updateBassFilterGain(int filterIdx, double gainDb) {
        short val = (short) Math.round(gainDb * 256.0);
        int offset = 11 + filterIdx * 10 + 8;
        liveBassFrame[offset] = (byte) (val & 0xFF);
        liveBassFrame[offset + 1] = (byte) ((val >> 8) & 0xFF);
        return liveBassFrame.clone();
    }

    /**
     * Set the gain of a specific filter inside Treble EQ (0x96)
     * @param filterIdx 0-based filter index (0 to 9)
     * @param gainDb Gain in decibels (-18.0 to +18.0 dB)
     */
    public static byte[] updateTrebleFilterGain(int filterIdx, double gainDb) {
        short val = (short) Math.round(gainDb * 256.0);
        int offset = 11 + filterIdx * 10 + 8;
        liveTrebleFrame[offset] = (byte) (val & 0xFF);
        liveTrebleFrame[offset + 1] = (byte) ((val >> 8) & 0xFF);
        return liveTrebleFrame.clone();
    }
